create table if not exists public.sales_client_launches (
  id uuid primary key default gen_random_uuid(),
  prospect_id uuid not null unique references public.prospects(id) on delete cascade,
  site_id uuid not null references public.sites(id) on delete cascade,
  onboarding_id uuid not null references public.sales_client_onboarding(id) on delete cascade,
  final_review_id uuid not null references public.sales_client_final_reviews(id) on delete restrict,
  balance_payment_id uuid not null unique references public.sales_payment_requests(id) on delete restrict,
  status text not null default 'preparing' check (status in ('preparing','ready','launched','handover_sent','completed')),
  handover_token uuid not null default gen_random_uuid() unique,
  handover_link_enabled boolean not null default false,
  approved_site_updated_at timestamptz not null,
  domain_ready boolean not null default false,
  https_ready boolean not null default false,
  website_health_ready boolean not null default false,
  mobile_reviewed boolean not null default false,
  contact_links_reviewed boolean not null default false,
  analytics_ready boolean not null default false,
  branding_reviewed boolean not null default false,
  launch_notes text not null default '',
  launched_at timestamptz null,
  handover_sent_at timestamptz null,
  handover_first_viewed_at timestamptz null,
  handover_last_viewed_at timestamptz null,
  handover_view_count integer not null default 0 check (handover_view_count >= 0),
  handover_acknowledged_at timestamptz null,
  handover_client_name text null,
  handover_client_email text null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid null
);
create index if not exists sales_client_launches_status_idx on public.sales_client_launches(status,updated_at desc);
alter table public.sales_client_launches enable row level security;
revoke all on public.sales_client_launches from anon,authenticated;

create or replace function public.sales_ensure_client_launch(p_payment_id uuid)
returns public.sales_client_launches language plpgsql security definer set search_path=public,pg_temp as $$
declare v_payment public.sales_payment_requests%rowtype; v_review public.sales_client_final_reviews%rowtype; v_onboarding public.sales_client_onboarding%rowtype; v_launch public.sales_client_launches%rowtype;
begin
 select * into v_payment from public.sales_payment_requests where id=p_payment_id;
 if not found or v_payment.kind<>'balance' or v_payment.status<>'paid' then raise exception 'Paid final balance required'; end if;
 select * into v_review from public.sales_client_final_reviews where prospect_id=v_payment.prospect_id and status='approved' order by version desc limit 1;
 if not found then raise exception 'Approved final review required'; end if;
 select * into v_onboarding from public.sales_client_onboarding where prospect_id=v_payment.prospect_id and status='completed';
 if not found then raise exception 'Completed onboarding required'; end if;
 insert into public.sales_client_launches(prospect_id,site_id,onboarding_id,final_review_id,balance_payment_id,approved_site_updated_at)
 values(v_payment.prospect_id,v_payment.site_id,v_onboarding.id,v_review.id,v_payment.id,v_review.site_updated_at)
 on conflict(prospect_id) do update set site_id=excluded.site_id,onboarding_id=excluded.onboarding_id,final_review_id=excluded.final_review_id,balance_payment_id=excluded.balance_payment_id,approved_site_updated_at=excluded.approved_site_updated_at,updated_at=now()
 returning * into v_launch;
 return v_launch;
end;$$;

create or replace function public.sales_client_launch_admin_get(p_prospect_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_launch public.sales_client_launches%rowtype; v_prospect public.prospects%rowtype; v_site public.sites%rowtype; v_onboarding public.sales_client_onboarding%rowtype; v_review public.sales_client_final_reviews%rowtype; v_payment public.sales_payment_requests%rowtype; v_paid public.sales_payment_requests%rowtype; v_checks_complete boolean; v_system_ready boolean;
begin
 if not public.is_labnarrative_admin() then raise exception 'Administrator access required'; end if;
 select * into v_prospect from public.prospects where id=p_prospect_id; if not found then raise exception 'Prospect not found'; end if;
 select * into v_launch from public.sales_client_launches where prospect_id=p_prospect_id;
 if not found then select * into v_paid from public.sales_payment_requests where prospect_id=p_prospect_id and kind='balance' and status='paid' order by paid_at desc limit 1; if found then begin select * into v_launch from public.sales_ensure_client_launch(v_paid.id); exception when others then null; end; end if; end if;
 select * into v_site from public.sites where id=v_prospect.site_id;
 select * into v_onboarding from public.sales_client_onboarding where prospect_id=p_prospect_id;
 select * into v_review from public.sales_client_final_reviews where prospect_id=p_prospect_id and status='approved' order by version desc limit 1;
 select * into v_payment from public.sales_payment_requests where prospect_id=p_prospect_id and kind='balance' order by created_at desc limit 1;
 if v_launch.id is not null then v_checks_complete:=v_launch.domain_ready and v_launch.https_ready and v_launch.website_health_ready and v_launch.mobile_reviewed and v_launch.contact_links_reviewed and v_launch.analytics_ready and v_launch.branding_reviewed; v_system_ready:=v_review.status='approved' and v_payment.status='paid' and v_onboarding.status='completed' and v_site.updated_at is not distinct from v_launch.approved_site_updated_at; else v_checks_complete:=false;v_system_ready:=false; end if;
 return jsonb_build_object('prospect',jsonb_build_object('id',v_prospect.id,'pi_name',v_prospect.pi_name,'institution',v_prospect.institution,'department',v_prospect.department,'email',v_prospect.email),'site',case when v_site.id is null then null else jsonb_build_object('id',v_site.id,'slug',v_site.slug,'status',v_site.status,'updated_at',v_site.updated_at,'domain_status',v_site.domain_status,'domain_url',v_site.domain_url) end,'onboarding',case when v_onboarding.id is null then null else jsonb_build_object('id',v_onboarding.id,'status',v_onboarding.status,'domain_choice',v_onboarding.domain_choice,'preferred_domain',v_onboarding.preferred_domain) end,'final_review',case when v_review.id is null then null else jsonb_build_object('id',v_review.id,'version',v_review.version,'status',v_review.status,'approved_at',v_review.approved_at,'site_updated_at',v_review.site_updated_at) end,'balance_payment',case when v_payment.id is null then null else jsonb_build_object('id',v_payment.id,'token',v_payment.token,'status',v_payment.status,'amount',v_payment.amount,'currency',v_payment.currency,'paid_at',v_payment.paid_at,'provider_capture_id',v_payment.provider_capture_id) end,'launch',case when v_launch.id is null then null else to_jsonb(v_launch) end,'checks_complete',v_checks_complete,'system_ready',v_system_ready,'ready_to_launch',coalesce(v_checks_complete,false) and coalesce(v_system_ready,false));
end;$$;

create or replace function public.sales_client_launch_admin_save(p_prospect_id uuid,p_domain_ready boolean,p_https_ready boolean,p_website_health_ready boolean,p_mobile_reviewed boolean,p_contact_links_reviewed boolean,p_analytics_ready boolean,p_branding_reviewed boolean,p_launch_notes text default null)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_client_launches%rowtype;v_site public.sites%rowtype;v_review public.sales_client_final_reviews%rowtype;v_payment public.sales_payment_requests%rowtype;v_onboarding public.sales_client_onboarding%rowtype;v_ready boolean;
begin
 if not public.is_labnarrative_admin() then raise exception 'Administrator access required'; end if;
 select * into v from public.sales_client_launches where prospect_id=p_prospect_id for update; if not found then raise exception 'Launch workspace is not available until the final balance is paid'; end if;
 if v.status in ('launched','handover_sent','completed') then raise exception 'Launch checklist is locked after launch'; end if;
 select * into v_site from public.sites where id=v.site_id;select * into v_review from public.sales_client_final_reviews where id=v.final_review_id;select * into v_payment from public.sales_payment_requests where id=v.balance_payment_id;select * into v_onboarding from public.sales_client_onboarding where id=v.onboarding_id;
 v_ready:=coalesce(p_domain_ready,false) and coalesce(p_https_ready,false) and coalesce(p_website_health_ready,false) and coalesce(p_mobile_reviewed,false) and coalesce(p_contact_links_reviewed,false) and coalesce(p_analytics_ready,false) and coalesce(p_branding_reviewed,false) and v_review.status='approved' and v_payment.status='paid' and v_onboarding.status='completed' and v_site.updated_at is not distinct from v.approved_site_updated_at;
 update public.sales_client_launches set domain_ready=coalesce(p_domain_ready,false),https_ready=coalesce(p_https_ready,false),website_health_ready=coalesce(p_website_health_ready,false),mobile_reviewed=coalesce(p_mobile_reviewed,false),contact_links_reviewed=coalesce(p_contact_links_reviewed,false),analytics_ready=coalesce(p_analytics_ready,false),branding_reviewed=coalesce(p_branding_reviewed,false),launch_notes=coalesce(p_launch_notes,''),status=case when v_ready then 'ready' else 'preparing' end,updated_at=now(),updated_by=auth.uid() where id=v.id returning * into v;
 return jsonb_build_object('ok',true,'launch',to_jsonb(v),'ready_to_launch',v_ready);
end;$$;

create or replace function public.sales_client_launch_admin_launch(p_prospect_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_client_launches%rowtype;v_site public.sites%rowtype;v_review public.sales_client_final_reviews%rowtype;v_payment public.sales_payment_requests%rowtype;v_onboarding public.sales_client_onboarding%rowtype;v_url text;
begin
 if not public.is_labnarrative_admin() then raise exception 'Administrator access required'; end if;
 select * into v from public.sales_client_launches where prospect_id=p_prospect_id for update;if not found then raise exception 'Launch workspace not found';end if;
 if v.status in ('launched','handover_sent','completed') then return jsonb_build_object('ok',true,'launch',to_jsonb(v)); end if;
 select * into v_site from public.sites where id=v.site_id for update;select * into v_review from public.sales_client_final_reviews where id=v.final_review_id;select * into v_payment from public.sales_payment_requests where id=v.balance_payment_id;select * into v_onboarding from public.sales_client_onboarding where id=v.onboarding_id;
 if v_review.status<>'approved' then raise exception 'Client final approval is required';end if;if v_payment.status<>'paid' then raise exception 'Final balance must be paid';end if;if v_onboarding.status<>'completed' then raise exception 'Client onboarding must be completed';end if;if v_site.updated_at is distinct from v.approved_site_updated_at then raise exception 'Website changed after client approval; prepare a new final review';end if;if v_onboarding.domain_choice='undecided' then raise exception 'Domain choice must be resolved before launch';end if;if v_onboarding.domain_choice in ('custom','institutional') and not(v_site.domain_status in ('live','wildcard_live','wildcard_ready') and coalesce(v_site.domain_url,'') like 'https://%') then raise exception 'Custom or institutional domain is not live with HTTPS';end if;if not(v.domain_ready and v.https_ready and v.website_health_ready and v.mobile_reviewed and v.contact_links_reviewed and v.analytics_ready and v.branding_reviewed) then raise exception 'Complete every launch checklist item first';end if;
 v_url:=coalesce(nullif(v_site.domain_url,''),'https://'||v_site.slug||'.labnarrative.com');
 update public.sites set status='live',outreach_status='client',updated_at=now() where id=v_site.id;
 update public.sales_client_launches set status='launched',handover_link_enabled=true,launched_at=now(),updated_at=now(),updated_by=auth.uid() where id=v.id returning * into v;
 update public.sales_lead_workspaces set stage='client',payment_status='paid_in_full',next_action='Send client handover',next_action_due_at=now(),updated_at=now(),updated_by=auth.uid() where prospect_id=v.prospect_id;
 insert into public.pipeline_events(prospect_id,event_type,step,message,payload,created_by) values(v.prospect_id,'website_launched','client_delivery','Client website launched after final approval and payment',jsonb_build_object('launch_id',v.id,'site_id',v.site_id,'url',v_url),auth.uid());
 return jsonb_build_object('ok',true,'launch',to_jsonb(v),'site_url',v_url,'handover_url','https://labnarrative.com/handover/'||v.handover_token::text);
end;$$;

create or replace function public.sales_client_launch_admin_mark_handover_sent(p_prospect_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_client_launches%rowtype;
begin
 if not public.is_labnarrative_admin() then raise exception 'Administrator access required';end if;select * into v from public.sales_client_launches where prospect_id=p_prospect_id for update;if not found or v.status not in ('launched','handover_sent') then raise exception 'Website must be launched first';end if;update public.sales_client_launches set status='handover_sent',handover_link_enabled=true,handover_sent_at=coalesce(handover_sent_at,now()),updated_at=now(),updated_by=auth.uid() where id=v.id returning * into v;update public.sales_lead_workspaces set next_action='Confirm client handover',next_action_due_at=now()+interval '3 days',updated_at=now(),updated_by=auth.uid() where prospect_id=v.prospect_id;insert into public.pipeline_events(prospect_id,event_type,step,message,payload,created_by) values(v.prospect_id,'handover_sent','client_delivery','Client handover link marked as sent',jsonb_build_object('launch_id',v.id),auth.uid());return jsonb_build_object('ok',true,'launch',to_jsonb(v),'handover_url','https://labnarrative.com/handover/'||v.handover_token::text);
end;$$;

create or replace function public.sales_client_handover_public_get(p_token uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_client_launches%rowtype;v_prospect public.prospects%rowtype;v_site public.sites%rowtype;v_onboarding public.sales_client_onboarding%rowtype;v_payment public.sales_payment_requests%rowtype;v_url text;
begin
 select * into v from public.sales_client_launches where handover_token=p_token and handover_link_enabled=true and status in ('launched','handover_sent','completed') for update;if not found then return jsonb_build_object('error','Handover link not found or disabled');end if;if v.status<>'completed' then update public.sales_client_launches set handover_first_viewed_at=coalesce(handover_first_viewed_at,now()),handover_last_viewed_at=now(),handover_view_count=handover_view_count+1,updated_at=now() where id=v.id returning * into v;end if;select * into v_prospect from public.prospects where id=v.prospect_id;select * into v_site from public.sites where id=v.site_id;select * into v_onboarding from public.sales_client_onboarding where id=v.onboarding_id;select * into v_payment from public.sales_payment_requests where id=v.balance_payment_id;v_url:=coalesce(nullif(v_site.domain_url,''),'https://'||v_site.slug||'.labnarrative.com');return jsonb_build_object('handover',jsonb_build_object('status',v.status,'launched_at',v.launched_at,'handover_sent_at',v.handover_sent_at,'acknowledged_at',v.handover_acknowledged_at,'client_name',v.handover_client_name),'prospect',jsonb_build_object('pi_name',v_prospect.pi_name,'institution',v_prospect.institution,'department',v_prospect.department),'site',jsonb_build_object('slug',v_site.slug,'url',v_url,'domain_status',v_site.domain_status),'domain',jsonb_build_object('choice',v_onboarding.domain_choice,'preferred_domain',v_onboarding.preferred_domain),'payment',jsonb_build_object('status',v_payment.status,'amount',v_payment.amount,'currency',v_payment.currency,'paid_at',v_payment.paid_at),'support',jsonb_build_object('email','khaled@labnarrative.com','provider','LabNarrative'));
end;$$;

create or replace function public.sales_client_handover_public_acknowledge(p_token uuid,p_name text,p_email text default null)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_client_launches%rowtype;
begin
 if coalesce(length(trim(p_name)),0)<2 then return jsonb_build_object('error','Please enter your name');end if;select * into v from public.sales_client_launches where handover_token=p_token and handover_link_enabled=true and status in ('launched','handover_sent','completed') for update;if not found then return jsonb_build_object('error','Handover link not found or disabled');end if;if v.status='completed' then return jsonb_build_object('ok',true,'status','completed');end if;update public.sales_client_launches set status='completed',handover_acknowledged_at=now(),handover_client_name=trim(p_name),handover_client_email=nullif(trim(coalesce(p_email,'')),''),updated_at=now() where id=v.id returning * into v;update public.sales_lead_workspaces set next_action='Offer LabNarrative Care',next_action_due_at=now()+interval '7 days',updated_at=now() where prospect_id=v.prospect_id;insert into public.pipeline_events(prospect_id,event_type,step,message,payload) values(v.prospect_id,'handover_acknowledged','client_delivery','Client acknowledged website handover',jsonb_build_object('launch_id',v.id,'client_name',trim(p_name)));return jsonb_build_object('ok',true,'status','completed','acknowledged_at',v.handover_acknowledged_at);
end;$$;

create or replace function public.sales_payment_provider_complete(p_payment_id uuid,p_order_id text,p_capture_id text,p_capture_status text,p_capture_amount numeric,p_capture_currency text,p_metadata jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_payment_requests%rowtype;v_site_id uuid;v_payer_name text;v_payer_email text;v_onboarding public.sales_client_onboarding%rowtype;v_launch public.sales_client_launches%rowtype;
begin
 select * into v from public.sales_payment_requests where id=p_payment_id for update;if not found then raise exception 'Payment request not found';end if;if v.status='paid' then if v.kind='deposit' then select * into v_onboarding from public.sales_client_onboarding where payment_id=v.id;if not found then perform public.sales_ensure_client_onboarding(v.id);end if;elsif v.kind='balance' then begin select * into v_launch from public.sales_ensure_client_launch(v.id);exception when others then null;end;end if;return to_jsonb(v);end if;if v.status in ('cancelled','expired','refunded') then raise exception 'Payment request is closed';end if;if coalesce(v.provider_order_id,'')<>coalesce(trim(p_order_id),'') then raise exception 'Provider order does not match this payment request';end if;if upper(coalesce(trim(p_capture_status),''))<>'COMPLETED' then raise exception 'Provider capture is not completed';end if;if p_capture_amount is null or round(p_capture_amount,2)<>round(v.amount,2) then raise exception 'Captured amount does not match the requested amount';end if;if upper(coalesce(trim(p_capture_currency),''))<>upper(v.currency) then raise exception 'Captured currency does not match the requested currency';end if;if coalesce(length(trim(p_capture_id)),0)=0 then raise exception 'Provider capture ID is required';end if;v_payer_name:=nullif(trim(coalesce(p_metadata#>>'{payer,name}','')),'');v_payer_email:=nullif(trim(coalesce(p_metadata#>>'{payer,email}','')),'');update public.sales_payment_requests set status='paid',provider_capture_id=trim(p_capture_id),paid_at=now(),payer_name=coalesce(v_payer_name,payer_name),payer_email=coalesce(v_payer_email,payer_email),provider_metadata=provider_metadata||coalesce(p_metadata,'{}'::jsonb),failure_message=null,failed_at=null,updated_at=now() where id=v.id returning * into v;select site_id into v_site_id from public.prospects where id=v.prospect_id;if v.kind='deposit' then update public.sales_lead_workspaces set stage='client',payment_status='deposit_received',deposit_amount=v.amount,deposit_percent=v.deposit_percent,deposit_received_at=now(),next_action='Send client onboarding link',next_action_due_at=now(),updated_at=now() where prospect_id=v.prospect_id;if v_site_id is not null then update public.sites set outreach_status='client',updated_at=now() where id=v_site_id;end if;update public.prospects set status='interested',updated_at=now() where id=v.prospect_id;select * into v_onboarding from public.sales_ensure_client_onboarding(v.id);insert into public.pipeline_events(prospect_id,event_type,step,message,payload) values(v.prospect_id,'deposit_received','sales_conversion','Deposit payment captured successfully; onboarding opened',jsonb_build_object('payment_id',v.id,'proposal_id',v.proposal_id,'amount',v.amount,'currency',v.currency,'provider',v.provider,'provider_order_id',p_order_id,'provider_capture_id',p_capture_id,'onboarding_id',v_onboarding.id));elsif v.kind='balance' then update public.sales_lead_workspaces set stage='client',payment_status='paid_in_full',next_action='Launch website',next_action_due_at=now(),updated_at=now() where prospect_id=v.prospect_id;select * into v_launch from public.sales_ensure_client_launch(v.id);insert into public.pipeline_events(prospect_id,event_type,step,message,payload) values(v.prospect_id,'final_balance_received','client_delivery','Final project balance captured successfully; launch workspace opened',jsonb_build_object('payment_id',v.id,'amount',v.amount,'currency',v.currency,'provider_order_id',p_order_id,'provider_capture_id',p_capture_id,'launch_id',v_launch.id));else update public.sales_lead_workspaces set next_action='Review received project payment',next_action_due_at=now(),updated_at=now() where prospect_id=v.prospect_id;end if;return to_jsonb(v);
end;$$;

create or replace function public.sales_payment_admin_mark_received(p_payment_id uuid,p_reference text default null,p_payer_name text default null,p_payer_email text default null)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.sales_payment_requests%rowtype;v_site_id uuid;v_onboarding public.sales_client_onboarding%rowtype;v_launch public.sales_client_launches%rowtype;
begin
 if not public.is_labnarrative_admin() then raise exception 'Administrator access required';end if;select * into v from public.sales_payment_requests where id=p_payment_id for update;if not found then raise exception 'Payment request not found';end if;if v.status='paid' then if v.kind='deposit' then select * into v_onboarding from public.sales_client_onboarding where payment_id=v.id;if not found then perform public.sales_ensure_client_onboarding(v.id);end if;elsif v.kind='balance' then begin select * into v_launch from public.sales_ensure_client_launch(v.id);exception when others then null;end;end if;return to_jsonb(v);end if;if v.status in ('cancelled','expired','refunded') then raise exception 'This payment request is not payable';end if;update public.sales_payment_requests set status='paid',paid_at=now(),updated_at=now(),updated_by=auth.uid(),provider_capture_id=coalesce(nullif(trim(p_reference),''),provider_capture_id),payer_name=coalesce(nullif(trim(p_payer_name),''),payer_name),payer_email=coalesce(nullif(trim(p_payer_email),''),payer_email),provider_metadata=provider_metadata||jsonb_build_object('manual_confirmation',true,'confirmed_by',auth.uid()) where id=v.id returning * into v;select site_id into v_site_id from public.prospects where id=v.prospect_id;if v.kind='deposit' then update public.sales_lead_workspaces set stage='client',payment_status='deposit_received',deposit_amount=v.amount,deposit_percent=v.deposit_percent,deposit_received_at=now(),next_action='Send client onboarding link',next_action_due_at=now(),updated_at=now(),updated_by=auth.uid() where prospect_id=v.prospect_id;if v_site_id is not null then update public.sites set outreach_status='client',updated_at=now() where id=v_site_id;end if;update public.prospects set status='interested',updated_at=now() where id=v.prospect_id;select * into v_onboarding from public.sales_ensure_client_onboarding(v.id);insert into public.pipeline_events(prospect_id,event_type,step,message,payload,created_by) values(v.prospect_id,'deposit_received','sales_conversion','Deposit payment manually confirmed; onboarding opened',jsonb_build_object('payment_id',v.id,'amount',v.amount,'currency',v.currency,'reference',p_reference,'onboarding_id',v_onboarding.id),auth.uid());elsif v.kind='balance' then update public.sales_lead_workspaces set stage='client',payment_status='paid_in_full',next_action='Launch website',next_action_due_at=now(),updated_at=now(),updated_by=auth.uid() where prospect_id=v.prospect_id;select * into v_launch from public.sales_ensure_client_launch(v.id);insert into public.pipeline_events(prospect_id,event_type,step,message,payload,created_by) values(v.prospect_id,'final_balance_received','client_delivery','Final project balance manually confirmed; launch workspace opened',jsonb_build_object('payment_id',v.id,'amount',v.amount,'currency',v.currency,'reference',p_reference,'launch_id',v_launch.id),auth.uid());else update public.sales_lead_workspaces set next_action='Review received project payment',next_action_due_at=now(),updated_at=now(),updated_by=auth.uid() where prospect_id=v.prospect_id;end if;return to_jsonb(v);
end;$$;

revoke all on function public.sales_ensure_client_launch(uuid) from public,anon,authenticated;grant execute on function public.sales_ensure_client_launch(uuid) to service_role;
